import { CLASSIFICATION } from '../config/classification';
import type { ParsedGame } from './pgn';

/**
 * Compact form of the lichess-org/chess-openings dataset (CC0), generated by
 * scripts/build-openings.mjs:
 *  - names: position key -> [eco, name] for every named line's final position
 *  - book:  position keys reached along named lines that have no name of their own
 */
export interface OpeningsData {
  names: Record<string, [eco: string, name: string]>;
  book: string[];
}

export interface Opening {
  eco: string;
  name: string;
}

/** Piece placement, side to move, castling rights, en passant (move counters dropped). */
export function positionKey(fen: string): string {
  return fen.split(' ').slice(0, 4).join(' ');
}

export interface OpeningBook {
  name(fen: string): Opening | undefined;
  contains(fen: string): boolean;
}

export function createBook(data: OpeningsData): OpeningBook {
  const extra = new Set(data.book);
  return {
    name(fen) {
      const hit = data.names[positionKey(fen)];
      return hit ? { eco: hit[0], name: hit[1] } : undefined;
    },
    contains(fen) {
      const key = positionKey(fen);
      return key in data.names || extra.has(key);
    },
  };
}

export interface BookInfo {
  /** isBook[i] is true if ply i is a book move (the game was in book through that ply). */
  isBook: boolean[];
  /** Name of the deepest named position reached so far, per ply. */
  openingAtPly: (Opening | undefined)[];
  /** The game's opening: the deepest named position reached. */
  opening: Opening | undefined;
}

export function detectBook(game: ParsedGame, book: OpeningBook, maxPly: number = CLASSIFICATION.book.maxPly): BookInfo {
  const isBook: boolean[] = [];
  const openingAtPly: (Opening | undefined)[] = [];
  let inBook = true;
  let current: Opening | undefined;
  game.plies.forEach((ply, i) => {
    if (i < maxPly) {
      const named = book.name(ply.fenAfter);
      if (named) current = named;
      inBook = inBook && (named !== undefined || book.contains(ply.fenAfter));
    } else {
      inBook = false;
    }
    isBook.push(inBook);
    openingAtPly.push(current);
  });
  return { isBook, openingAtPly, opening: current };
}

let loaded: Promise<OpeningBook> | null = null;

/** Lazily load the bundled dataset (a separate chunk, fetched on first use). */
export function loadOpeningBook(): Promise<OpeningBook> {
  loaded ??= import('../data/openings.json').then((m) => createBook((m.default ?? m) as unknown as OpeningsData));
  return loaded;
}
